import { MCPServerStreamableHttp } from "@openai/agents";

const viktor = new MCPServerStreamableHttp({
  name: "viktor",
  url: "{{MCP_URL}}",
  requestInit: { headers: { Authorization: `Bearer ${process.env.{{KEY_ENV}}}` } },
});

import { createMCPClient } from "@ai-sdk/mcp";

const viktor = await createMCPClient({
  transport: { type: "http", url: "{{MCP_URL}}", headers: { Authorization: `Bearer ${process.env.{{KEY_ENV}}}` } },
});
const tools = await viktor.tools();

import { MCPClient } from "@mastra/mcp";

const mcp = new MCPClient({ servers: { viktor: {
  url: new URL("{{MCP_URL}}"),
  requestInit: { headers: { Authorization: `Bearer ${process.env.{{KEY_ENV}}}` } },
} } });
const tools = await mcp.getTools();

import { MultiServerMCPClient } from "@langchain/mcp-adapters";

const client = new MultiServerMCPClient({ viktor: {
  url: "{{MCP_URL}}",
  headers: { Authorization: `Bearer ${process.env.{{KEY_ENV}}}` },
} });
const tools = await client.getTools();

